import {createContext, use} from 'react'
import type {ReactNode} from 'react'

// =============================================================================
// DynamicChunkCollector – SSR-time chunk collection for dynamic() components
// =============================================================================
//
// During SSR, tracks which dynamic() chunk names were rendered so the server
// can emit the CSS <link> and JS <link rel="modulepreload"> tags needed for
// the current page.
//
// Usage (SSR handler):
//   const collector = new DynamicChunkCollector()
//   const html = renderToString(
//     <DynamicChunkProvider collector={collector}>
//       <App />
//     </DynamicChunkProvider>
//   )
//   const renderedChunks = collector.getChunks()
//   // Look up chunk names in dynamicChunkMap to get CSS + JS file URLs
//

/**
 * Lightweight set-based collector that dynamic() components register into
 * during server rendering. No-op on the client (context returns null).
 */
export class DynamicChunkCollector {
  #chunks = new Set<string>()

  /** Register a dynamic chunk name as rendered during SSR. */
  addChunk(chunkName: string): void {
    this.#chunks.add(chunkName)
  }

  /** Get all chunk names that were rendered during this SSR pass. */
  getChunks(): string[] {
    return Array.from(this.#chunks)
  }

  /** Reset for reuse across requests (alloy worker pooling). */
  reset(): void {
    this.#chunks.clear()
  }
}

/**
 * React context for the chunk collector. Defaults to null (client-side).
 * Only has a value when wrapped in DynamicChunkProvider during SSR.
 */
export const DynamicChunkContext = createContext<DynamicChunkCollector | null>(null)
DynamicChunkContext.displayName = 'DynamicChunkContext'

/**
 * Hook to access the current chunk collector. Returns null on the client
 * or when no provider is present (safe to call unconditionally).
 */
export function useDynamicChunkCollector(): DynamicChunkCollector | null {
  return use(DynamicChunkContext)
}

/**
 * Provider component for SSR. Wrap your app in this before renderToString().
 */
export function DynamicChunkProvider({collector, children}: {collector: DynamicChunkCollector; children: ReactNode}) {
  return <DynamicChunkContext value={collector}>{children}</DynamicChunkContext>
}
