/**
 * Server-side implementation of dynamic().
 *
 * Resolved via package.json conditional exports when `target: 'node22'` (Alloy SSR).
 * The Alloy bundle uses rspack's `dynamicMode: 'eager'` so import() calls resolve
 * synchronously — preload() at module init primes the cache for getResolved().
 */
import type {ComponentPropsWithRef, ComponentType, FC} from 'react'
import {ComponentResource} from './component-resource'
import {useDynamicChunkCollector} from './dynamic-chunk-collector'
import type {DynamicClientOnlyOptions, DynamicComponent, DynamicOptions} from './dynamic-types'

// eslint-disable-next-line no-barrel-files/no-barrel-files
export type {DynamicOptions, DynamicComponent, DynamicClientOnlyOptions} from './dynamic-types'

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export function dynamic<T extends ComponentType<any>>(
  load: () => Promise<{default: T}>,
  options: DynamicOptions = {},
): DynamicComponent<T> {
  if (options.ssr === false) {
    return dynamicClientOnly(load, {loading: options.loading ?? null, displayName: options.displayName})
  }

  const syncModule = '__sync' in options && options.__sync ? options.__sync : undefined
  const resource = new ComponentResource(load, syncModule)
  const name = options.displayName
  const chunkName = options.chunkName
  const displayName = name ? `DYNAMIC(${name})` : 'DYNAMIC'

  // Prewarm: with dynamicMode: 'sync', the babel plugin injects __sync with a
  // synchronously resolved module, so ComponentResource is immediately ready.
  // For Vite dev server or when __sync is not present, fall back to eager mode:
  // call preload() to kick off the .then() microtask that populates #result.
  if (!syncModule) {
    void resource.preload()
  }

  const DynamicComponent: FC<ComponentPropsWithRef<T>> = props => {
    const chunkCollector = useDynamicChunkCollector()
    if (chunkCollector && chunkName) {
      chunkCollector.addChunk(chunkName)
    }

    const Resolved = resource.getResolved()
    // eslint-disable-next-line react-hooks/static-components -- stable component ref from getResolved()
    if (Resolved) return <Resolved {...props} />

    // Safety fallback — should not happen with eager mode, but if it does
    // React.lazy will suspend and the caller's Suspense boundary handles it.
    return <resource.Lazy {...props} />
  }

  return Object.assign(DynamicComponent, {
    preload: () => resource.preload(),
    ssr: true,
    Loading: null,
    displayName,
  }) as DynamicComponent<T>
}

/**
 * Server-side dynamicClientOnly: always renders the fallback/loading component.
 * The real component is never loaded on the server.
 */
// eslint-disable-next-line @typescript-eslint/no-explicit-any
function dynamicClientOnly<T extends ComponentType<any>>(
  _load: () => Promise<{default: T}>,
  options: DynamicClientOnlyOptions = {},
): DynamicComponent<T> {
  const {loading: Loading = null, displayName: name} = options
  const displayName = name ? `DYNAMIC-CLIENT(${name})` : 'DYNAMIC-CLIENT'

  const ServerFallback: FC<ComponentPropsWithRef<T>> = () => {
    return Loading ? <Loading /> : null
  }

  return Object.assign(ServerFallback, {
    // No-op on server — never load the real component
    preload: () => Promise.resolve({default: (() => null) as unknown as T}),
    ssr: false,
    Loading,
    displayName,
  }) as DynamicComponent<T>
}
